package org.sleepmonitor.app;
import android.content.*;import android.bluetooth.*;import android.os.*;import android.bluetooth.le.*;import java.util.*;
final class WitSensor {
 static final String[] LABELS={"Ruecken","Bauch","Links","Rechts"};
 static final UUID S=witUuid("ffe5"),N=witUuid("ffe4"),W=witUuid("ffe9"),D=uuid("2902");
 static UUID witUuid(String s){return UUID.fromString("0000"+s+"-0000-1000-8000-00805f9a34fb");}
 static boolean isNotify(UUID u){return N.equals(u)||uuid("ffe4").equals(u);}
 static boolean isService(UUID u){return S.equals(u)||uuid("ffe5").equals(u);}
 UUID selectedNotify; BluetoothGattCharacteristic batteryWriter;
 static volatile int centivolts=-1; static volatile long batteryTime=0; long lastQuery=0; static volatile long batteryWall,queries,answers; static volatile boolean polling=true; static volatile double hz; static volatile String link="Gestoppt"; long rateStart,ratePackets; static volatile double beforeQueryHz; static volatile long queryMono; static volatile boolean pending; static volatile String queryResult="–";
 static int percent(int cv){return cv<0?-1:Math.max(0,Math.min(100,(int)Math.round((cv-320)*100.0/90)));}
 static int voltage(){return batteryTime>0&&SystemClock.elapsedRealtime()-batteryTime<150000?centivolts:-1;}
 static int battery(){return percent(voltage());}
 static String batteryCsv(){int v=voltage();return v<0?",,":","+percent(v)+","+String.format(Locale.US,"%.2f",v/100.0);}
 void queryBattery(){if(!polling||!ready||g==null||batteryWriter==null||!fresh(sample)||hz<1)return;long now=SystemClock.elapsedRealtime();if(lastQuery!=0&&now-lastQuery<60000)return;lastQuery=now;queries++;beforeQueryHz=hz;queryMono=now;pending=true;queryResult="Warte auf Antwort";note("Akku TX FF AA 27 64 00 | vorher Hz="+hz);try{batteryWriter.setWriteType((batteryWriter.getProperties()&BluetoothGattCharacteristic.PROPERTY_WRITE_NO_RESPONSE)!=0?BluetoothGattCharacteristic.WRITE_TYPE_NO_RESPONSE:BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT);batteryWriter.setValue(new byte[]{(byte)0xff,(byte)0xaa,0x27,0x64,0});if(!g.writeCharacteristic(batteryWriter)){pending=false;queryResult="Schreiben abgelehnt";note(queryResult);}}catch(Exception e){note("Akkuabfrage: "+e.getClass().getSimpleName());}}
 static String batteryLabel(){int v=centivolts;return v<0?"–":String.format(Locale.GERMANY,"ca. %d %% (%.2f V) · %s%s",percent(v),v/100.0,new java.text.SimpleDateFormat("HH:mm:ss",Locale.GERMANY).format(new Date(batteryWall)),voltage()<0||!fresh(sample)?" · letzter Wert":"");}

 static UUID uuid(String s){return UUID.fromString("0000"+s+"-0000-1000-8000-00805f9b34fb");}
 static volatile String status="Bereit", error="–", raw="–"; static volatile long notifications; static final ArrayDeque<String> log=new ArrayDeque<>(); static synchronized void note(String s){if(log.size()>=1000)log.removeFirst();log.add(System.currentTimeMillis()+" "+s);status=s;} static synchronized String diagnostic(){return String.join("\n",log)+"\nLetzter Fehler: "+error+"\nRAW: "+raw;} static volatile Sample sample; static volatile long packets,reconnects;
 static final double[][] refs=new double[4][];
 static class Sample {final long wall,mono;final double[] v;Sample(byte[] b,long w,long m){wall=w;mono=m;v=new double[9];for(int i=0;i<9;i++){int j=2+2*i;v[i]=(short)((b[j]&255)|((b[j+1]&255)<<8))*(i<3?16.0:i<6?2000.0:180.0)/32768.0;}}}
 static boolean fresh(Sample s){return s!=null&&SystemClock.elapsedRealtime()-s.mono<2000;}
 static double norm(double[] v){return Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);}
 static synchronized void load(Context c){for(int i=0;i<4;i++){refs[i]=null;String s=c.getSharedPreferences("wit",0).getString("ref"+i,"");try{String[] a=s.split(";");refs[i]=new double[]{Double.parseDouble(a[0]),Double.parseDouble(a[1]),Double.parseDouble(a[2])};}catch(Exception ignored){}}}
 static synchronized boolean calibrate(Context c,int i){Sample s=sample;if(!fresh(s))return false;double n=norm(s.v);if(n<0.85||n>1.15||Math.abs(s.v[3])+Math.abs(s.v[4])+Math.abs(s.v[5])>10)return false;double[] a={s.v[0]/n,s.v[1]/n,s.v[2]/n};for(int j=0;j<4;j++)if(j!=i&&refs[j]!=null&&dot(a,refs[j])>0.7)return false;refs[i]=a;c.getSharedPreferences("wit",0).edit().putString("ref"+i,a[0]+";"+a[1]+";"+a[2]).apply();return true;}
 static double dot(double[] a,double[] b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
 static synchronized String position(Sample s){if(!fresh(s))return "missing";for(double[] r:refs)if(r==null)return "uncalibrated";double n=norm(s.v);if(n<0.8||n>1.2||Math.abs(s.v[3])+Math.abs(s.v[4])+Math.abs(s.v[5])>15)return "moving";double best=-2,second=-2;int k=0;for(int i=0;i<4;i++){double d=dot(s.v,refs[i])/n;if(d>best){second=best;best=d;k=i;}else if(d>second)second=d;}return best>=0.82&&best-second>=0.15?LABELS[k]:"uncertain";}
 static synchronized String calibration(){int n=0;for(double[] r:refs)if(r!=null)n++;return n+"/4";}
 static synchronized void clear(Context c){Arrays.fill(refs,null);c.getSharedPreferences("wit",0).edit().clear().apply();}
 final Context c;final Handler h;BluetoothGatt g;boolean active;long since;boolean ready,scanning,cacheTried; BluetoothLeScanner scanner;
 WitSensor(Context c,Handler h){this.c=c;this.h=h;}
 void start(){active=true;cacheTried=false;sample=null;centivolts=-1;batteryTime=batteryWall=queries=answers=0;hz=0;rateStart=SystemClock.elapsedRealtime();ratePackets=0;pending=false;queryResult="–";packets=reconnects=notifications=0;error=raw="–";synchronized(WitSensor.class){log.clear();}connect();h.post(watch);}
 void connect(){if(!active||g!=null||scanning)return;try{link="Suche";note("WIT Scan");since=SystemClock.elapsedRealtime();BluetoothAdapter a=c.getSystemService(BluetoothManager.class).getAdapter();scanner=a.getBluetoothLeScanner();if(scanner==null){retry("Scanner fehlt");return;}scanning=true;scanner.startScan(Arrays.asList(new ScanFilter.Builder().setDeviceName("WT901BLE67").build(),new ScanFilter.Builder().setDeviceAddress("D7:AC:65:C5:E8:8B").build()),new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),scanCb);}catch(Exception e){retry("Scan: "+e);}}
 final ScanCallback scanCb=new ScanCallback(){public void onScanResult(int t,ScanResult r){h.post(()->{if(!active||!scanning)return;stopScan();try{note("WIT gefunden "+r.getDevice().getAddress()+" RSSI "+r.getRssi());since=SystemClock.elapsedRealtime();g=r.getDevice().connectGatt(c,false,cb,BluetoothDevice.TRANSPORT_LE);if(g==null)retry("connectGatt null");}catch(Exception e){retry("Connect: "+e);}});}public void onScanFailed(int code){h.post(()->{if(active&&scanning)retry("Scanfehler "+code);});}};
 void stopScan(){if(scanning){scanning=false;try{scanner.stopScan(scanCb);}catch(Exception ignored){}}}
 void retry(String why){if(!active)return;error=why;note("WIT Fehler: "+why);reconnects++;stopScan();closeGatt();h.removeCallbacks(reconnect);h.postDelayed(reconnect,6000);}
 final Runnable reconnect=()->connect();
 final Runnable watch=new Runnable(){public void run(){if(!active)return;if(scanning&&SystemClock.elapsedRealtime()-since>20000)retry("Scan Timeout");else if(g!=null&&SystemClock.elapsedRealtime()-since>20000&&(!ready||!fresh(sample)))retry("Timeout: "+status);long now=SystemClock.elapsedRealtime();if(now-rateStart>=5000){hz=(packets-ratePackets)*1000.0/(now-rateStart);rateStart=now;ratePackets=packets;if(pending&&now-queryMono>10000){pending=false;queryResult="Antwort-Timeout";note(queryResult+" | Hz="+hz);}if(queryMono>0&&now-queryMono>=10000&&now-queryMono<16000)note("Akku Frequenzvergleich: vorher="+beforeQueryHz+" nachher="+hz);}if(ready)queryBattery();h.postDelayed(this,2000);}};
 void closeGatt(){sample=null;ready=false;selectedNotify=null;batteryWriter=null;lastQuery=0;pending=false;link="Getrennt";BluetoothGatt old=g;g=null;if(old!=null)try{old.close();}catch(Exception ignored){}}
 void stop(){active=false;stopScan();h.removeCallbacks(watch);h.removeCallbacks(reconnect);closeGatt();status="Gestoppt";link="Gestoppt";}
 final BluetoothGattCallback cb=new BluetoothGattCallback(){
 public void onConnectionStateChange(BluetoothGatt x,int s,int state){h.post(()->{if(x!=g||!active)return;try{if(s!=0||state!=BluetoothProfile.STATE_CONNECTED){retry("GATT status="+s+" state="+state);return;}note("WIT GATT verbunden; Dienste in 2s");since=SystemClock.elapsedRealtime();h.postDelayed(()->{if(x!=g||!active)return;try{note("WIT discoverServices");if(!x.discoverServices())retry("discoverServices false");}catch(Exception e){retry("Discovery: "+e);}},2000);}catch(Exception e){retry("GATT: "+e);}});}
 public void onServicesDiscovered(BluetoothGatt x,int s){h.post(()->{if(x!=g||!active)return;try{if(s!=0){retry("Discovery status="+s);return;} BluetoothGattService svc=x.getService(S);if(svc==null)svc=x.getService(uuid("ffe5"));BluetoothGattCharacteristic n=null;note("WIT Dienste Anzahl="+x.getServices().size()+" erwartet="+S+" / "+N);for(BluetoothGattService service:x.getServices()){note("Service "+service.getUuid());for(BluetoothGattCharacteristic ch:service.getCharacteristics()){note("Char "+ch.getUuid()+" props=0x"+Integer.toHexString(ch.getProperties()));for(BluetoothGattDescriptor desc:ch.getDescriptors())note("Descriptor "+desc.getUuid());if(isNotify(ch.getUuid())&&(ch.getProperties()&BluetoothGattCharacteristic.PROPERTY_NOTIFY)!=0&&(n==null||isService(service.getUuid())))n=ch;}}note("FFE5="+(svc!=null)+" FFE4 notify="+(n!=null));if(n==null){if(!cacheTried){cacheTried=true;try{Object result=x.getClass().getMethod("refresh").invoke(x);note("GATT Cache refresh (optional): "+result);}catch(Exception e){note("GATT Cache refresh nicht verfuegbar: "+e.getClass().getSimpleName());}}retry("FFE4 fehlt in Dienstliste");return;}BluetoothGattService ns=n.getService();batteryWriter=ns.getCharacteristic(W);if(batteryWriter==null)batteryWriter=ns.getCharacteristic(uuid("ffe9"));if(batteryWriter!=null&&(batteryWriter.getProperties()&12)==0)batteryWriter=null;selectedNotify=n.getUuid();note("WIT ausgewählte Notify UUID: "+selectedNotify);if(!x.setCharacteristicNotification(n,true)){retry("FFE4 lokale Notify Aktivierung false");return;}BluetoothGattDescriptor d=n.getDescriptor(D);if(d==null){retry("CCCD fehlt");return;}d.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);note("WIT CCCD schreiben");since=SystemClock.elapsedRealtime();if(!x.writeDescriptor(d))retry("CCCD write false");}catch(Exception e){retry("Dienste: "+e);}});}
 public void onDescriptorWrite(BluetoothGatt x,BluetoothGattDescriptor d,int s){h.post(()->{if(x!=g||!active)return;if(!D.equals(d.getUuid())||!d.getCharacteristic().getUuid().equals(selectedNotify))return;if(s!=0){retry("CCCD status="+s);return;}ready=true;link="Verbunden";since=SystemClock.elapsedRealtime();cacheTried=false;note("WIT Notify aktiv");});}
 public void onCharacteristicWrite(BluetoothGatt x,BluetoothGattCharacteristic ch,int result){h.post(()->{if(x==g&&ch==batteryWriter&&result!=0)note("Akku Schreibstatus="+result);});}
 public void onCharacteristicChanged(BluetoothGatt x,BluetoothGattCharacteristic ch){byte[] b=ch.getValue();if(b!=null)accept(x,ch,b.clone());}
 public void onCharacteristicChanged(BluetoothGatt x,BluetoothGattCharacteristic ch,byte[] b){accept(x,ch,b.clone());}
 void accept(BluetoothGatt x,BluetoothGattCharacteristic ch,byte[] b){long w=System.currentTimeMillis(),m=SystemClock.elapsedRealtime();UUID u=ch.getUuid();h.post(()->{if(x!=g||!active||!u.equals(selectedNotify))return;notifications++;StringBuilder hex=new StringBuilder();for(byte v:b){int n=v&255;hex.append("0123456789ABCDEF".charAt(n>>>4)).append("0123456789ABCDEF".charAt(n&15)).append(' ');}raw=hex.toString();if(b.length>=6&&b[0]==0x55&&b[1]==0x71&&b[2]==0x64&&b[3]==0){int cv=(b[4]&255)|((b[5]&255)<<8);if(cv>=250&&cv<=450){centivolts=cv;batteryTime=m;batteryWall=w;answers++;pending=false;queryResult="OK";note("WIT Akku "+cv+" cV | RX "+raw+" | Antwort ms="+(m-queryMono));}else note("WIT Akku Register ungültig: "+cv);return;}if(b.length!=20||b[0]!=0x55||b[1]!=0x61){if(notifications<=5)note("Unerwartetes Paket: "+raw);return;}sample=new Sample(b,w,m);packets++;if(packets==1)note("WIT erstes gültiges 55 61 Paket: "+raw);status="WIT Daten aktiv";});}
 };
 static String csv(long now){Sample s=sample;if(!fresh(s))return ",,,,,,,,,,,,missing";StringBuilder b=new StringBuilder();b.append(',').append(s.wall).append(',').append(now-s.wall);for(double v:s.v)b.append(',').append(String.format(Locale.US,"%.5f",v));return b.append(',').append(position(s)).toString();}
 static String live(){Sample s=sample;return link+" | "+String.format(Locale.GERMANY,"%.1f Hz",hz)+" | Akku TX/RX: "+queries+"/"+answers+" | "+queryResult+"\n"+batteryLabel()+"\n"+status+" | Pakete: "+packets+" | Reconnects: "+reconnects+"\nLetzter Fehler: "+error+"\nNotify: "+notifications+"\nRAW: "+raw+"\nKalibrierung: "+calibration()+(fresh(s)?String.format(Locale.US,"\nXYZ g: %.3f / %.3f / %.3f\nGyro: %.1f / %.1f / %.1f\nWinkel: %.1f / %.1f / %.1f\nLage: %s",s.v[0],s.v[1],s.v[2],s.v[3],s.v[4],s.v[5],s.v[6],s.v[7],s.v[8],position(s)):"\nKeine aktuellen Lagedaten");}
}
